// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Mining_Command_Delivery_Api {
  def id: Art.BridgeId
  def mining_in_Id : Art.PortId
  def mining_out_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var mining_out: Mining_Threat_Retreat_Supervisor.Mining_Command.Type = $

  def put_mining_out(value : Mining_Threat_Retreat_Supervisor.Mining_Command.Type) : Unit = {
    Contract(
      Modifies(mining_out),
      Ensures(
        mining_out == value
      )
    )
    Spec {
      mining_out = value
    }

    Art.putValue(mining_out_Id, Mining_Threat_Retreat_Supervisor.Mining_Command_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Mining_Command_Delivery_Initialization_Api (
  val id: Art.BridgeId,
  val mining_in_Id : Art.PortId,
  val mining_out_Id : Art.PortId) extends Mining_Command_Delivery_Api

@datatype class Mining_Command_Delivery_Operational_Api (
  val id: Art.BridgeId,
  val mining_in_Id : Art.PortId,
  val mining_out_Id : Art.PortId) extends Mining_Command_Delivery_Api {

  // Logika spec var representing port state for incoming data port
  @spec var mining_in: Mining_Threat_Retreat_Supervisor.Mining_Command.Type = $

  def get_mining_in() : Option[Mining_Threat_Retreat_Supervisor.Mining_Command.Type] = {
    Contract(
      Ensures(
        Res == Some(mining_in)
      )
    )
    val value : Option[Mining_Threat_Retreat_Supervisor.Mining_Command.Type] = Art.getValue(mining_in_Id) match {
      case Some(Mining_Threat_Retreat_Supervisor.Mining_Command_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port mining_in.  Expecting 'Mining_Threat_Retreat_Supervisor.Mining_Command_Payload' but received ${v}")
        None[Mining_Threat_Retreat_Supervisor.Mining_Command.Type]()
      case _ => None[Mining_Threat_Retreat_Supervisor.Mining_Command.Type]()
    }
    return value
  }
}
